@Override
    public void curioTick(SlotContext slotContext, ItemStack stack) {
        super.curioTick(slotContext, stack);

        if (!(slotContext.entity() instanceof LivingEntity entity))
            return;

        var level = entity.level();
        var belowState = level.getBlockState(entity.getBlockPosBelowThatAffectsMyMovement());

        var ability = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch");
        var forcedFall = this.isForcedFall(stack);
        var onGround = entity.onGround();
        var glitchEnabled = this.isGlitchEnabled(entity, stack);

        if (!glitchEnabled) {
            this.setStandTicks(stack, 0);
            this.setForcedFall(stack, false);
            this.setPhaseTicks(stack, 0);
        } else {
            var stable = onGround && belowState.isAir() && !isMovingHorizontally(entity) && !entity.isShiftKeyDown();

            if (!forcedFall) {
                if (stable) {
                    this.addStandTicks(stack, 1);

                    if (this.getStandTicks(stack) >= (int) Math.max(1D, ability.getStatData("stability_time").getValue() * 20D)) {
                        this.setForcedFall(stack, true);
                        this.setForcedFallStartY(stack, entity.getY());
                        this.setStandTicks(stack, 0);

                        if (!level.isClientSide())
                            this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch").getStatisticData().getMetricData("forced_falls").addValue(1);
                    }
                } else {
                    this.setStandTicks(stack, 0);
                }
            }

            if (this.isForcedFall(stack) && onGround && !belowState.isAir() && entity.fallDistance <= 0F)
                this.setForcedFall(stack, false);
        }

        if (level.isClientSide())
            return;

        var gameTime = level.getGameTime();

        if (glitchEnabled && belowState.isAir() && this.canCollideWithAirLike(entity, stack) && this.getLastAirTick(stack) != gameTime) {
            this.setLastAirTick(stack, gameTime);

            ability.getStatisticData().getMetricData("solid_air_duration").addValue(1D / 20D);

            if (isMovingHorizontally(entity))
                this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "air_walking", 1D / 20D);
        }

        var illusion = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("illusion");

        if (illusion.canPlayerUse(entity) && illusion.getMode().equals("enabled")) {
            if (this.getIllusionCooldown(stack) > 0) {
                this.addIllusionCooldown(stack, -1);
            } else {
                var look = entity.getLookAngle().multiply(1D, 0D, 1D);
                var backward = look.lengthSqr() > 1.0E-6D ? look.normalize().scale(-0.95D) : Vec3.ZERO;
                var spawnPos = entity.position().add(backward);
                var copy = new GlitchyIllusionEntity(RelicsEntities.GLITCHY_ILLUSION.get(), level);

                copy.setOwner(entity);
                copy.setLifetime((int) Math.max(1D, illusion.getStatData("duration").getValue() * 20D));
                copy.setStunDuration((int) Math.max(1D, illusion.getStatData("stun").getValue() * 20D));
                copy.setStunRadius((float) Math.max(0D, illusion.getStatData("stun_radius").getValue()));
                copy.setFlawless(this.getRelicData(entity, stack).isVisuallyFlawless());
                copy.setStack(stack);
                copy.setPos(spawnPos.x(), spawnPos.y(), spawnPos.z());
                copy.setYRot(entity.getYRot());
                copy.setXRot(entity.getXRot());
                copy.setYHeadRot(entity.getYHeadRot());
                copy.setSnapshotXRot(entity.getXRot());
                copy.setPose(entity.getPose());

                if (level.getEntitiesOfClass(GlitchyIllusionEntity.class, copy.getBoundingBox().inflate(0.05D)).isEmpty()) {
                    level.addFreshEntity(copy);

                    this.setIllusionCooldown(stack, (int) Math.max(1D, illusion.getStatData("interval").getValue() * 20D));
                    illusion.getStatisticData().getMetricData("illusions").addValue(1);
                    this.getRelicData(entity, stack).getLevelingData().addExperience("illusion", "creation", 1);
                }
            }
        } else {
            this.setIllusionCooldown(stack, 0);
        }

        if (glitchEnabled && ability.getRankModifierData("phase").isEnabled()) {
            var eyesInsideBlock = areEyesInsideCollidingBlock(entity);

            if (!eyesInsideBlock) {
                this.setLastSafePosition(stack, entity.position());
                this.setPhaseTicks(stack, 0);
            } else {
                if (this.getLastPhaseTick(stack) != gameTime) {
                    this.setLastPhaseTick(stack, gameTime);

                    ability.getStatisticData().getMetricData("phase_duration").addValue(1D / 20D);
                    this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "phasing", 1D / 20D);
                }

                if (!level.isClientSide())
                    entity.addEffect(new MobEffectInstance(RelicsMobEffects.GLITCH, 5, 0, false, false));

                this.addPhaseTicks(stack, 1);

                var limit = Math.max(1, (int) Math.round(ability.getStatData("phase_time").getValue() * 20D));

                if (this.getPhaseTicks(stack) > limit) {
                    var pos = this.getLastSafePosition(stack);

                    if (entity instanceof ServerPlayer serverPlayer) {
                        serverPlayer.teleportTo(serverPlayer.serverLevel(), pos.x(), pos.y(), pos.z(), entity.getYRot(), entity.getXRot());
                        serverPlayer.setDeltaMovement(Vec3.ZERO);
                    } else {
                        entity.teleportTo(pos.x(), pos.y(), pos.z());
                        entity.setDeltaMovement(Vec3.ZERO);
                    }

                    level.playSound(null, BlockPos.containing(pos), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1F, 1F);

                    this.setPhaseTicks(stack, 0);
                    ability.getStatisticData().getMetricData("phase_rollbacks").addValue(1);
                }
            }
        }
    }

@SubscribeEvent
        public static void onLivingIncomingDamage(LivingIncomingDamageEvent event) {
            if (event.getEntity() instanceof Player player && !player.level().isClientSide()) {
                var attacker = event.getSource().getEntity() instanceof LivingEntity livingAttacker ? livingAttacker : null;

                if (attacker == null && event.getSource().getDirectEntity() instanceof Projectile projectile
                        && projectile.getOwner() instanceof LivingEntity projectileOwner) {
                    attacker = projectileOwner;
                }

                if (attacker != null && attacker != player) {
                    for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GLITCHY_MANTLE.get())) {
                        var relic = (GlitchyMantleItem) stack.getItem();
                        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("distortion");

                        if (!ability.canPlayerUse(player) || !TargetingUtils.canHarm(player, attacker, stack, "distortion"))
                            continue;

                        if (player.getRandom().nextDouble() >= ability.getStatData("miss_chance").getValue())
                            continue;

                        event.setCanceled(true);

                        player.addEffect(new MobEffectInstance(RelicsMobEffects.GLITCH, 10, 0, false, false));

                        ability.getStatisticData().getMetricData("misses").addValue(1);
                        relic.getRelicData(player, stack).getLevelingData().addExperience("distortion", "miss", 1);

                        if (ability.getRankModifierData("disorientation").isEnabled()) {
                            var rotation = attacker.getRandom().nextFloat() * 360F;

                            if (attacker instanceof ServerPlayer serverAttacker)
                                serverAttacker.teleportTo(serverAttacker.serverLevel(), serverAttacker.getX(), serverAttacker.getY(), serverAttacker.getZ(), rotation, serverAttacker.getXRot());

                            attacker.setYRot(rotation);
                            attacker.setYHeadRot(rotation);
                            attacker.setYBodyRot(rotation);
                            attacker.yRotO = rotation;
                            attacker.yHeadRotO = rotation;
                            attacker.yBodyRotO = rotation;

                            if (attacker instanceof Mob mob) {
                                mob.setTarget(null);

                                var radians = Math.toRadians(rotation);
                                var direction = new Vec3(-Math.sin(radians), 0D, Math.cos(radians));
                                var destination = mob.position().add(direction.scale(3D));

                                mob.getNavigation().stop();
                                mob.getNavigation().moveTo(destination.x(), destination.y(), destination.z(), 1D);
                            }
                        }

                        return;
                    }
                }
            }

            if (!event.getContainer().getSource().is(DamageTypes.IN_WALL))
                return;

            var entity = event.getEntity();

            for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.GLITCHY_MANTLE.get())) {
                var relic = (GlitchyMantleItem) stack.getItem();
                var ability = relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch");

                if (relic.isGlitchEnabled(entity, stack) && ability.getRankModifierData("phase").isEnabled()) {
                    event.setCanceled(true);

                    return;
                }
            }
        }

@SubscribeEvent
        public static void onLivingDamage(LivingDamageEvent.Pre event) {
            if (ECHOING_ATTACK.get() || !(event.getSource().getEntity() instanceof Player source)) {
                return;
            }

            if (!event.getSource().is(DamageTypes.PLAYER_ATTACK) || event.getSource().getDirectEntity() != source)
                return;

            var target = event.getEntity();

            for (var stack : EntityUtils.findEquippedCurios(source, RelicsItems.GLITCHY_MANTLE.get())) {
                var relic = (GlitchyMantleItem) stack.getItem();
                var ability = relic.getRelicData(source, stack).getAbilitiesData().getAbilityData("illusion");

                if (!ability.canPlayerUse(source) || !ability.getMode().equals("enabled") || !ability.getRankModifierData("echo").isEnabled())
                    continue;

                var radius = source.getAttributeValue(Attributes.ENTITY_INTERACTION_RANGE) * ability.getStatData("echo_radius").getValue();
                var illusions = source.level().getEntitiesOfClass(GlitchyIllusionEntity.class, target.getBoundingBox().inflate(radius), illusion -> illusion.getOwner() == source)
                        .stream()
                        .sorted(java.util.Comparator.comparingDouble(illusion -> illusion.distanceToSqr(target)))
                        .toList();

                if (illusions.isEmpty())
                    return;

                ECHOING_ATTACK.set(true);

                var damageDealt = 0D;

                try {
                    for (var illusion : illusions) {
                        illusion.startEchoAttack(target, source.getMainHandItem());
                        target.invulnerableTime = 0;

                        if (TargetingUtils.hurtEnemy(target, event.getSource(), event.getNewDamage(), stack, "illusion"))
                            damageDealt += event.getNewDamage();
                    }
                } finally {
                    ECHOING_ATTACK.set(false);
                }

                ability.getStatisticData().getMetricData("echo_attacks").addValue(illusions.size());
                ability.getStatisticData().getMetricData("damage_dealt").addValue(damageDealt);
                relic.getRelicData(source, stack).getLevelingData().addExperience("illusion", "echo_attack", illusions.size());

                return;
            }
        }

public int getIllusionCooldown(ItemStack stack) {
        return stack.getOrDefault(RelicsDataComponents.GLITCHY_MANTLE_ILLUSION_COOLDOWN, 0);
    }

public void setIllusionCooldown(ItemStack stack, int cooldown) {
        stack.set(RelicsDataComponents.GLITCHY_MANTLE_ILLUSION_COOLDOWN, Math.max(0, cooldown));
    }

public long getLastPhaseTick(ItemStack stack) {
        return stack.getOrDefault(RelicsDataComponents.GLITCHY_MANTLE_LAST_PHASE_TICK, Long.MIN_VALUE);
    }

public void setLastPhaseTick(ItemStack stack, long tick) {
        stack.set(RelicsDataComponents.GLITCHY_MANTLE_LAST_PHASE_TICK, tick);
    }

@Override
    public void tick() {
        super.tick();

        this.setDeltaMovement(0D, 0D, 0D);

        if (!this.level().isClientSide() && this.getEchoAttackTicks() > 0) {
            this.getEntityData().set(ECHO_ATTACK_TICKS, this.getEchoAttackTicks() - 1);

            if (this.getEchoAttackTicks() <= 0)
                this.getEntityData().set(ECHO_ATTACK_ITEM, ItemStack.EMPTY);
        }

        if (this.tickCount > this.getLifetime()) {
            if (!this.level().isClientSide())
                this.spawnGlitchDissolve();

            this.discard();

            return;
        }

        this.tickElectricSynergy();

        if (this.level().isClientSide())
            return;

        var owner = this.getOwner();

        if (this.checkOwnerProjectileHits(owner))
            return;

        var hitTargets = this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox(), entity -> this.canAffectTarget(entity, owner));

        if (hitTargets.isEmpty())
            return;

        this.detonate(owner, false);
    }

@Nullable
    public LivingEntity getOwner() {
        var ownerId = this.getEntityData().get(OWNER_ID);
        var entity = ownerId >= 0 ? this.level().getEntity(ownerId) : null;

        if (entity instanceof LivingEntity owner) {
            if (!this.level().isClientSide())
                this.ownerUuid = owner.getUUID();

            return owner;
        }

        if (this.level().isClientSide() || this.ownerUuid == null || !(this.level() instanceof ServerLevel serverLevel))
            return null;

        var uuidEntity = serverLevel.getEntity(this.ownerUuid);

        if (uuidEntity instanceof LivingEntity owner) {
            this.getEntityData().set(OWNER_ID, owner.getId());

            return owner;
        }

        return null;
    }

private void tickElectricSynergy() {
        var owner = this.getOwner();

        if (owner == null)
            return;

        ElectricSynergy synergy;

        if (this.level().isClientSide()) {
            if (!this.isElectricChainActive())
                return;

            synergy = new ElectricSynergy(0F, this.isElectricChainFlawless());
        } else {
            synergy = resolveElectricSynergy(owner);

            this.setElectricChainState(synergy != null, synergy != null && synergy.flawless());
        }

        if (synergy == null)
            return;

        var illusions = this.level().getEntitiesOfClass(GlitchyIllusionEntity.class, owner.getBoundingBox().inflate(96D),
                        illusion -> illusion.isAlive() && illusion.getOwner() == owner)
                .stream()
                .sorted(Comparator.comparingInt(GlitchyIllusionEntity::getId))
                .toList();

        if (illusions.size() < 2 || illusions.getFirst() != this)
            return;

        var damagedTargets = new HashSet<UUID>();

        for (var i = 1; i < illusions.size(); i++) {
            var previous = illusions.get(i - 1);
            var current = illusions.get(i);
            var start = previous.position().add(0D, previous.getBbHeight() * 0.55D, 0D);
            var end = current.position().add(0D, current.getBbHeight() * 0.55D, 0D);

            if (this.level().isClientSide())
                this.spawnElectricChainParticles(start, end, synergy.flawless());
            else
                this.hurtElectricChainTargets(owner, start, end, synergy.damage(), damagedTargets);
        }
    }

@Nullable
    private static ElectricSynergy resolveElectricSynergy(LivingEntity owner) {
        var hasShock = EntityUtils.findEquippedCurios(owner, RelicsItems.JELLYFISH_NECKLACE.get()).stream()
                .filter(stack -> stack.getItem() instanceof JellyfishNecklaceItem relic
                        && relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("shock").canPlayerUse(owner))
                .anyMatch(stack -> {
                    var relic = (JellyfishNecklaceItem) stack.getItem();
                    return relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("shock").getMode().equals("enabled");
                });

        if (!hasShock)
            return null;

        var damage = 0D;
        var flawless = false;

        for (var stack : EntityUtils.findEquippedCurios(owner, RelicsItems.GLITCHY_MANTLE.get())) {
            if (!(stack.getItem() instanceof GlitchyMantleItem relic))
                continue;

            var relicData = relic.getRelicData(owner, stack);
            var illusion = relicData.getAbilitiesData().getAbilityData("illusion");
            var synergy = relicData.getAbilitiesData().getSynergyData("electricity");

            if (!illusion.canPlayerUse(owner) || !illusion.getMode().equals("enabled") || !synergy.isUnlocked() || !synergy.getMode().equals("enabled"))
                continue;

            damage = Math.max(damage, synergy.getStatData("damage").getValue());
            flawless |= relicData.isVisuallyFlawless();
        }

        return damage > 0D ? new ElectricSynergy((float) damage, flawless) : null;
    }

private void hurtElectricChainTargets(LivingEntity owner, Vec3 start, Vec3 end, float damage, HashSet<UUID> damagedTargets) {
        var radius = 0.35D;
        var segmentBox = new AABB(
                Math.min(start.x, end.x) - radius,
                Math.min(start.y, end.y) - radius,
                Math.min(start.z, end.z) - radius,
                Math.max(start.x, end.x) + radius,
                Math.max(start.y, end.y) + radius,
                Math.max(start.z, end.z) + radius
        );

        for (var target : this.level().getEntitiesOfClass(LivingEntity.class, segmentBox,
                entity -> entity != owner && entity.isAlive() && TargetingUtils.canHarmSynergy(owner, entity, this.getStack(), "electricity"))) {
            if (!target.getBoundingBox().inflate(0.1D).clip(start, end).isPresent() || !damagedTargets.add(target.getUUID()))
                continue;

            TargetingUtils.hurtEnemyBySynergy(target, this.level().damageSources().thrown(this, owner), damage, this.getStack(), "electricity");
        }
    }

private boolean checkOwnerProjectileHits(@Nullable LivingEntity owner) {
        if (owner == null)
            return false;

        var bounds = this.getBoundingBox().inflate(0.12D);

        for (var projectile : this.level().getEntitiesOfClass(Projectile.class, bounds.inflate(1D),
                projectile -> projectile.isAlive() && projectile.getOwner() == owner)) {
            var start = new Vec3(projectile.xOld, projectile.yOld, projectile.zOld);
            var end = projectile.position();

            if (bounds.intersects(projectile.getBoundingBox()) || bounds.clip(start, end).isPresent()) {
                this.detonate(owner, true);

                return true;
            }
        }

        return false;
    }

@Override
    public boolean hurt(DamageSource source, float amount) {
        if (this.level().isClientSide())
            return false;

        var owner = this.getOwner();
        var attacker = source.getEntity();
        var direct = source.getDirectEntity();

        if (direct == this || owner == null || attacker == null || !owner.getUUID().equals(attacker.getUUID()))
            return false;

        this.detonate(owner, true);

        return true;
    }

private void detonate(@Nullable LivingEntity owner, boolean byOwner) {
        if (this.level().isClientSide())
            return;

        var radius = this.getStunRadius();
        var radiusSqr = radius * radius;
        var stunnedTargets = 0;

        for (var target : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(radius), entity -> this.canAffectTarget(entity, owner))) {
            if (target.distanceToSqr(this) <= radiusSqr) {
                TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.STUN, this.getStunDuration(), 0, false, false), owner, this.getStack(), "illusion");
                TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.GLITCH, this.getStunDuration(), 0, false, false), owner, this.getStack(), "illusion");

                stunnedTargets++;
            }
        }

        this.addDetonationExperience(owner, byOwner, stunnedTargets);
        this.spawnGlitchBurst();
        this.discard();
    }

public void startEchoAttack(LivingEntity target, ItemStack stack) {
        var dx = target.getX() - this.getX();
        var dz = target.getZ() - this.getZ();
        var rotation = (float) (Mth.atan2(dz, dx) * (180F / Math.PI)) - 90F;
        var dy = target.getEyeY() - this.getEyeY();
        var horizontalDistance = Math.sqrt(dx * dx + dz * dz);
        var headPitch = (float) -(Mth.atan2(dy, horizontalDistance) * (180F / Math.PI));

        this.setYRot(rotation);
        this.setYHeadRot(rotation);
        this.setXRot(headPitch);
        this.getEntityData().set(ECHO_ATTACK_TICKS, ECHO_ATTACK_DURATION);
        this.getEntityData().set(ECHO_ATTACK_ITEM, stack.copy());
        this.getEntityData().set(ECHO_HEAD_PITCH, headPitch);
    }

@Override
    public void readAdditionalSaveData(CompoundTag tag) {
        this.setLifetime(tag.getInt("lifetime"));
        this.setStunDuration(tag.getInt("stunDuration"));
        this.setStunRadius(tag.getFloat("stunRadius"));
        this.setFlawless(tag.getBoolean("flawless"));
        this.setSnapshotXRot(tag.getFloat("snapshotXRot"));

        if (tag.hasUUID("owner"))
            this.ownerUuid = tag.getUUID("owner");

        this.setStack(ItemStack.parseOptional(this.registryAccess(), tag.getCompound("stack")));
    }

@Override
    public void addAdditionalSaveData(CompoundTag tag) {
        tag.putInt("lifetime", this.getLifetime());
        tag.putInt("stunDuration", this.getStunDuration());
        tag.putFloat("stunRadius", this.getStunRadius());
        tag.putBoolean("flawless", this.isFlawless());
        tag.putFloat("snapshotXRot", this.getSnapshotXRot());

        if (this.ownerUuid != null)
            tag.putUUID("owner", this.ownerUuid);

        tag.put("stack", this.getStack().saveOptional(this.registryAccess()));
    }

@Override
    protected void tick() {
        if (getWorld().isClientSide) {
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), 5);
        } else {
            if (getWorld().getGameTime() % 100 == 0) {
                List<LivingEntity> entities = getWorld().getEntitiesOfClass(LivingEntity.class, new AABB(getPos()).inflate(5));
                Optional<LivingEntity> player = entities.stream().filter(e -> e instanceof Player).findFirst();

                boolean didWorkOnce = false;
                for (LivingEntity a : entities) {
                    if (a instanceof ZombieVillager zv) {
                        zv.startConverting(player.map(Entity::getUUID).orElse(null), 0);
                        didWorkOnce = true;
                        continue;
                    }

                    if (a.getHealth() < a.getMaxHealth() || a.isInvertedHealAndHarm()) {
                        if (a.isInvertedHealAndHarm()) {
                            FakePlayer player1 = ANFakePlayer.getPlayer((ServerLevel) getWorld());
                            a.hurt(getWorld().damageSources().playerAttack(player1), 10.0f);
                        } else {
                            a.heal(10.0f);
                        }
                        didWorkOnce = true;
                    }
                }
                if (didWorkOnce)
                    setNeedsSource(true);
            }
        }
    }

@Override
    public int getSourceCost() {
        return 200;
    }

public void tryTick(RitualBrazierTile tickingTile) {
        if (tickingTile == null || !getContext().isStarted || getContext().isDone) {
            return;
        }
        this.tile = tickingTile;
        tick();
    }

public void setNeedsSource(boolean needMana) {
        getContext().needsSourceToRun = needMana;
        BlockUtil.safelyUpdateState(getWorld(), tile.getBlockPos());
    }

public boolean needsSourceNow() {
        return getContext().needsSourceToRun;
    }

public boolean consumesSource() {
        return getSourceCost() > 0;
    }

@Override
    public void tick() {
        if (isDecorative && level.isClientSide) {
            makeParticle(color.nextColor((int) level.getGameTime() * 20), color.nextColor((int) level.getGameTime() * 20 + 200), 10);
            return;
        }


        if (level.isClientSide && ritual != null) {
            makeParticle(ritual.getCenterColor(), ritual.getOuterColor(), ritual.getParticleIntensity());
        }
        if (isOff)
            return;
        if (ritual != null) {

            if (ritual.getContext().isDone) {
                ritual.onEnd();
                ritual = null;
                getLevel().playSound(null, getBlockPos(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0f, 1.0f);
                getLevel().setBlock(getBlockPos(), getLevel().getBlockState(getBlockPos()).setValue(RitualBrazierBlock.LIT, false), 3);
                updateBlock();
                return;
            }
            if (!ritual.isRunning() && !level.isClientSide && level.getGameTime() % 5 == 0) {
                level.getEntitiesOfClass(ItemEntity.class, new AABB(getBlockPos()).inflate(1)).forEach(i -> {
                    tryBurnStack(i.getItem());
                });
            }
            if (ritual.consumesSource() && ritual.needsSourceNow()) {
                if (this.sourceBackoff-- <= 0) {
                    int cost = ritual.getSourceCost();
                    if (SourceUtil.takeSourceMultipleWithParticles(getBlockPos(), getLevel(), 6, cost) != null) {
                        ritual.setNeedsSource(false);
                        this.sourceBackoff = 0;
                        updateBlock();
                    } else {
                        this.sourceBackoff = 20;
                        return;
                    }
                } else {
                    return;
                }
            }
            if (this.relayPos != null && level.isLoaded(this.relayPos) && level.getBlockEntity(this.relayPos) instanceof BrazierRelayTile relayTile) {
                ritual.tryTick(relayTile);
                relayTile.ticksToLightOff = 2;
                relayTile.isDecorative = false;
            } else {
                ritual.tryTick(this);
            }
        }
    }

@Override
	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		/* Default Ritual Stuff */
		Level world = masterRitualStone.getWorldObj();
		int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();
		BlockPos pos = masterRitualStone.getMasterBlockPos();

		if (currentEssence < getRefreshCost())
		{
			masterRitualStone.getOwnerNetwork().causeNausea();
			return;
		}

		int maxEffects = currentEssence / getRefreshCost();
		int totalEffects = 0;

		/* Default will augment stuff */
		List<EnumDemonWillType> willConfig = masterRitualStone.getActiveWillConfig();
		DemonWillHolder holder = WorldDemonWillHandler.getWillHolder(world, pos);

		double rawWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DEFAULT, willConfig);
		double corrosiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.CORROSIVE, willConfig);
		double destructiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DESTRUCTIVE, willConfig);
		double steadfastWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.STEADFAST, willConfig);
		double vengefulWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.VENGEFUL, willConfig);

		double rawDrained = 0;
		double corrosiveDrained = 0;
		double destructiveDrained = 0;
		double steadfastDrained = 0;
		double vengefulDrained = 0;

		/* Actual ritual stuff begins here */
		AreaDescriptor groundingRange = masterRitualStone.getBlockRange(GROUNDING_RANGE);
		List<LivingEntity> entities = world.getEntitiesOfClass(LivingEntity.class, groundingRange.getAABB(pos));
		for (LivingEntity entity : entities)
		{
			if (totalEffects >= maxEffects)
			{
				break;
			}

			if (entity instanceof Player && ((Player) entity).isCreative())
				continue;

			totalEffects++;

			if (entity instanceof Player)
			{
				/* Raw will effect: Affects players */
				if (world.getGameTime() % 10 == 0)
				{
					if (rawWill >= willDrain)
					{

						rawDrained += willDrain;

						double[] drainagePlayer = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

						corrosiveDrained += drainagePlayer[0];
						destructiveDrained += drainagePlayer[1];
						vengefulDrained += drainagePlayer[2];
					}
				}
			} else if (entity.canChangeDimensions())
			{
				if (world.getGameTime() % 10 == 0)
				{
					double[] drainageEntity = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

					corrosiveDrained += drainageEntity[0];
					destructiveDrained += drainageEntity[1];
					vengefulDrained += drainageEntity[2];
				}
			} else if (!entity.canChangeDimensions())
			{
				/*
				 * Steadfast will effect: Affects bosses (some bosses, like the wither, have a
				 * restriction to motion modification, others, like the Ender Dragon, don't do
				 * potions)
				 */
				if (steadfastWill >= willDrain)
				{
					if (entity instanceof WitherBoss || entity instanceof EnderDragon)
						entity.move(MoverType.SELF, new Vec3(0, -0.05, 0)); // to work on Wither and EnderDragon
																				// without
					// interfering with other mod author's decisions
					// (looking at you, Vazkii)

					steadfastDrained += willDrain / 10f;

					double[] drainagePlayer = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

					corrosiveDrained += drainagePlayer[0];
					destructiveDrained += drainagePlayer[1];
					vengefulDrained += drainagePlayer[2];
				}
			}
		}

		if (rawDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DEFAULT, rawDrained, true);
		if (corrosiveDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.CORROSIVE, corrosiveDrained, true);
		if (destructiveDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DESTRUCTIVE, destructiveDrained, true);
		if (steadfastDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.STEADFAST, steadfastDrained, true);
		if (vengefulDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.VENGEFUL, vengefulDrained, true);

		masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(getRefreshCost() * totalEffects));
	}

public double[] sharedWillEffects(Level world, LivingEntity entity, double corrosiveWill, double destructiveWill, double vengefulWill, double corrosiveDrained, double destructiveDrained, double vengefulDrained)
	{
		/* Corrosive will effect: Suspension */
		if (corrosiveWill >= willDrain)
		{

			entity.addEffect(new MobEffectInstance(BloodMagicPotions.SUSPENDED.get(), 20, 0));
			corrosiveDrained += willDrain;

			/* Vengeful will effect: Levitation */
		} else if (vengefulWill >= willDrain)
		{

			vengefulDrained += willDrain;
			entity.addEffect(new MobEffectInstance(MobEffects.LEVITATION, 20, 10));

		} else
		{
			entity.addEffect(new MobEffectInstance(BloodMagicPotions.GROUNDED.get(), 20, 0));
			entity.addEffect(new MobEffectInstance(BloodMagicPotions.GRAVITY.get(), 20, 0));
		}

		/* Destructive will effect: Increased fall damage */
		if (destructiveWill >= willDrain)
		{
			destructiveDrained += willDrain;

			entity.addEffect(new MobEffectInstance(BloodMagicPotions.HEAVY_HEART.get(), 100, 1));
		}
		return new double[] { corrosiveDrained, destructiveDrained, vengefulDrained };
	}

