public void shootFissureAtTarget(LivingEntity target, Vec3 prevTargetPos, float timeScale) {
            EntityFissure fissure = new EntityFissure(EntityHandler.FISSURE.get(), getLevel());
            fissure.setOwner(getUser());
            fissure.setPos(getUser().position());

            Vec3 shootVec;
            if (target != null) {
                float speed = EntityFissurePiece.PIECE_SIZE / (float) EntityFissure.TICKS_PER_PIECE;
                Vec3 targetPos = target.position().add(0, target.getBbHeight() / 2.0, 0);
                double timeToReach = fissure.position().subtract(targetPos).length() / speed;
                Vec3 targetMovement = targetPos.subtract(prevTargetPos).scale(timeToReach * timeScale * 1.0 / 4.0);
                targetMovement = targetMovement.multiply(1, 0, 1);
                Vec3 futureTargetPos = targetPos.add(targetMovement);
                Vec3 projectileMid = fissure.position().add(0, fissure.getBbHeight() / 2.0, 0);
                shootVec = futureTargetPos.subtract(projectileMid).normalize();
            }
            else {
                shootVec = getUser().getForward();
            }

            fissure.shoot(shootVec.x, shootVec.z);
            getLevel().addFreshEntity(fissure);
        }

public void tick() {
            LivingEntity livingentity = this.bluff.getTarget();
            if (livingentity != null) {
                double d0 = this.bluff.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
                boolean flag = this.bluff.getSensing().hasLineOfSight(livingentity);
                boolean flag1 = this.seeTime > 0;
                if (flag != flag1) {
                    this.seeTime = 0;
                }

                if (flag) {
                    ++this.seeTime;
                } else {
                    --this.seeTime;
                }

                if (!(d0 > (double)this.attackMaxRadiusSqr) && this.seeTime >= 20) {
                    this.bluff.getNavigation().stop();
                    ++this.strafingTime;
                } else {
                    this.bluff.getNavigation().moveTo(livingentity, this.speedModifier);
                    this.strafingTime = -1;
                }

                if (this.strafingTime >= 20) {
                    if ((double)this.bluff.getRandom().nextFloat() < 0.3D) {
                        this.isStrafing = !this.isStrafing;
                    }

                    if ((double)this.bluff.getRandom().nextFloat() < 0.3D) {
                        this.strafingClockwise = !this.strafingClockwise;
                    }

                    if ((double)this.bluff.getRandom().nextFloat() < 0.3D) {
                        this.strafingBackwards = !this.strafingBackwards;
                    }

                    this.strafingTime = 0;
                }

                if (this.strafingTime > -1) {
                    if (d0 > (double)(this.attackMaxRadiusSqr)) {
                        this.strafingBackwards = false;
                    } else if (d0 < (double)(this.attackMinRadiusSqr)) {
                        this.strafingBackwards = true;
                    }

                    if (isStrafing) {
                        this.bluff.getMoveControl().strafe(this.strafingBackwards ? -0.3F : 0.3F, this.strafingClockwise ? 0.3F : -0.3F);
                    }
                    else {
                        this.bluff.getMoveControl().strafe(0, 0);
                    }
                    this.bluff.lookAt(livingentity, 30.0F, 30.0F);
                }
                this.bluff.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);

                if (--this.attackTime <= 0 && this.seeTime >= -60 && d0 < attackMaxRadiusSqr) {
                    bluff.sendAbilityMessage(ATTACK_ABILITY);
                    this.attackTime = attackIntervalMin + bluff.random.nextInt(40);
                }
            }
        }

public void stop() {
            super.stop();
            this.bluff.setAggressive(false);
            this.seeTime = 0;
        }

@Override
    public void tick() {
        super.tick();
        if (isTravelling()) {
            stepForwardTrace();
        }

        if (tickCount > 60 && isTravelling()) spawnSpike();
        if (despawnTimer > 0) {
            despawnTimer--;
            if (despawnTimer == 1) discard();
        }

        if (!level().isClientSide()) {
            if (isTravelling() && tickCount % TICKS_PER_PIECE == 1f) {
                EntityFissurePiece piece = new EntityFissurePiece(EntityHandler.FISSURE_PIECE.get(), level());
                piece.setPos(position().add(getDeltaMovement().scale(TICKS_PER_PIECE/3f)));
                piece.setYRot(getYRot());
                piece.setOwner(this);
                level().addFreshEntity(piece);
            }

            if (isTravelling() && !level().getEntities(this, getBoundingBox().inflate(0.3), e -> e.canBeHitByProjectile() && e != getOwner() && !(e instanceof EntityBluff)).isEmpty()) {
                spawnSpike();
            }
        }
        else {
            if (tickCount == 1) {
                MMCommon.PROXY.playGeomancyRumbleSound(this);
            }
            if (isTravelling()) {
                BlockState blockBeneath = level().getBlockState(getOnPos());
                for (int i = 0; i < 10; i++) {
                    Vec3 offset = new Vec3(random.nextFloat() * 0.45, 0, 0).yRot(random.nextFloat() * (float) Math.PI * 2f);
                    Vec3 vel = offset.normalize().scale(random.nextGaussian() * 0.12).yRot(random.nextFloat() * 0.2f - 0.1f).add(0, random.nextDouble() * 0.25 + 0.02, 0).add(getDeltaMovement().scale(0.4));
                    AdvancedTerrainParticle.spawnTerrainParticle(level(), ParticleHandler.TERRAIN, getX() + offset.x, getY(), getZ() + offset.z, vel.x, vel.y, vel.z, 0, 0.4f + random.nextGaussian() * 0.3, 0.94f, 20 + random.nextFloat() * 5, blockBeneath, new ParticleComponent[]{
                            new ParticleComponent.Gravity(1)
                    });
                }
            }
        }
    }

private void spawnSpike() {
        if (isTravelling()) {
            if (!level().isClientSide()) {
                BlockState state = level().getBlockState(getOnPos());
                if (!EffectGeomancy.isBlockUseable(state)) {
                    state = Blocks.DIRT.defaultBlockState();
                }
                EntityEarthSpike spike = new EntityEarthSpike(EntityHandler.EARTH_SPIKE.get(), level(), (LivingEntity) getOwner(), state);
                spike.setPos(position());
                spike.setYRot(getYRot());
                level().addFreshEntity(spike);
            }
            setTravelling(false);
            despawnTimer = 180;
            setDeltaMovement(0,0,0);
        }
    }

public void stepForwardTrace() {
        Vec3 forwardPos = position().add(getDeltaMovement());
        Vec3 startPos = forwardPos.add(0, 1.1, 0);
        Vec3 endPos = forwardPos.add(0, -1.1, 0);
        BlockHitResult result = level().clip(new ClipContext(startPos, endPos, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));

        if (result.getType() != HitResult.Type.BLOCK || result.isInside()) {
            spawnSpike();
            return;
        }
        setPos(result.getLocation());
        if (this.level() instanceof ServerLevel) {
            ((ServerLevel) this.level()).getChunkSource().broadcast(this, new ClientboundTeleportEntityPacket(this));
        }
    }

public void addAdditionalSaveData(CompoundTag compound) {
        super.addAdditionalSaveData(compound);
        compound.putShort("despawnTimer", (short)this.despawnTimer);
        compound.putBoolean("travelling", isTravelling());
    }

public void readAdditionalSaveData(CompoundTag compound) {
        super.readAdditionalSaveData(compound);
        this.despawnTimer = compound.getShort("despawnTimer");
        setTravelling(compound.getBoolean("travelling"));
    }

@Override
    public void tick() {
        super.tick();

        if (damageDelay >= 0) --damageDelay;

        if (!emerged) {
            emerged = true;
            damageDelay = 2;
            playSound(MMSounds.ENTITY_BLUFF_SPIKE_EMERGE.get(), 1, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            if (level().isClientSide()) {
                for (int i = 0; i < 30; i++) {
                    Vec3 offset = new Vec3(0.6 + random.nextFloat() * 0.2, 0.1, 0).yRot(random.nextFloat() * (float) Math.PI * 2f);
                    Vec3 vel = offset.normalize().scale(random.nextGaussian() * 0.12).yRot(random.nextFloat() * 0.2f - 0.1f).add(0, random.nextDouble() * 0.45 + 0.2, 0).add(getForward().scale(0.1));
                    AdvancedTerrainParticle.spawnTerrainParticle(level(), ParticleHandler.TERRAIN, getX() + offset.x, getY(), getZ() + offset.z, vel.x, vel.y, vel.z, 0, 0.4f + random.nextGaussian() * 0.3, 0.94f, 25 + random.nextFloat() * 10, getBlock(), new ParticleComponent[]{
                            new ParticleComponent.Gravity(1)
                    });
                }
            }
        }

        if (damageDelay == 0 && !level().isClientSide()) {
            damageDelay = -1;
            List<Entity> entitiesHit = level().getEntities(this, getBoundingBox().inflate(0.4), e -> e.canBeHitByProjectile() && e != getCaster() && !(e instanceof ItemEntity));
            double damage = 10;
            if (getCaster() != null) {
                if (getCaster() instanceof EntityBluff) {
                    AttributeInstance attrib = getCaster().getAttribute(Attributes.ATTACK_DAMAGE);
                    if (attrib != null) {
                        damage = attrib.getValue();
                    }
                    damage = damage * ConfigHandler.COMMON.MOBS.BLUFF.combatConfig.attackMultiplier.get();
                }
            }
            for (Entity entity : entitiesHit) {
                if (getCaster() instanceof EntityBluff && entity instanceof EntityBluff) continue;
                if (entity instanceof ItemEntity) continue;
                entity.hurt(damageSources().mobProjectile(this, getCaster()), (float) damage);
                float applyKnockbackResistance = 0;
                if (entity instanceof LivingEntity) {
                    applyKnockbackResistance = (float) ((LivingEntity) entity).getAttribute(Attributes.KNOCKBACK_RESISTANCE).getValue();
                }
                double y = 0;
                if (entity.onGround()) {
                    y += 0.15 * (1 - applyKnockbackResistance);
                }
                entity.setDeltaMovement(entity.getDeltaMovement().add(0, y, 0));
                if (entity instanceof ServerPlayer) {
                    ((ServerPlayer) entity).connection.send(new ClientboundSetEntityMotionPacket(entity));
                }
            }
        }
    }

@Override
    public void addAdditionalSaveData(CompoundTag compound) {
        super.addAdditionalSaveData(compound);
        compound.putBoolean("emerged", emerged);
    }

@Override
    public void readAdditionalSaveData(CompoundTag compound) {
        super.readAdditionalSaveData(compound);
        emerged = compound.getBoolean("emerged");
    }
